import{_ as o,r as a,o as p,c,e as n,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"Resources - October CMS - 3.x","titleTemplate":false,"description":"Внедрение ресурсов, переменных и заголовков на страницу.","frontmatter":{"subtitle":"Внедрение ресурсов, переменных и заголовков на страницу."},"headers":[{"level":2,"title":"Доступные свойства","slug":"доступные-своиства","link":"#доступные-своиства","children":[]},{"level":2,"title":"Базовое использование","slug":"базовое-использование","link":"#базовое-использование","children":[]},{"level":2,"title":"Внедрение переменных","slug":"внедрение-переменных","link":"#внедрение-переменных","children":[]},{"level":2,"title":"Внедрение ресурсов","slug":"внедрение-ресурсов","link":"#внедрение-ресурсов","children":[]},{"level":2,"title":"Использование пользовательских заголовков","slug":"использование-пользовательских-заголовков","link":"#использование-пользовательских-заголовков","children":[]}],"relativePath":"3.x/ru/cms/components/resources.md","filePath":"3.x/ru/cms/components/resources.md"}'),u={name:"3.x/ru/cms/components/resources.md"};function i(k,s,d,g,v,m){const t=a("pre-heading"),e=a("post-heading");return p(),c("div",null,[n(t),s[0]||(s[0]=l("h1",null,"Resources",-1)),n(e),s[1]||(s[1]=r(`<p>Компонент <code>resources</code> может создавать новые переменные, добавлять заголовки и внедрять ресурсы на страницу. Компонент resources может использоваться на любой странице, макете или фрагменте.</p><h2 id="доступные-своиства"><a href="#доступные-своиства" class="header-anchor">#</a> Доступные свойства</h2><p>Компонент поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>js</strong></td><td>Массив JavaScript-файлов в папке <strong>assets/js</strong> темы</td></tr><tr><td><strong>less</strong></td><td>Массив LESS-файлов в папке <strong>assets/less</strong> темы</td></tr><tr><td><strong>scss</strong></td><td>Массив SCSS-файлов в папке <strong>assets/scss</strong> темы</td></tr><tr><td><strong>css</strong></td><td>Массив файлов стилей в папке <strong>assets/css</strong> темы</td></tr><tr><td><strong>vars</strong></td><td>Включает переменные, доступные на странице или макете.</td></tr><tr><td><strong>headers</strong></td><td>Включает заголовки в ответ страницы.</td></tr></tbody></table></div><h2 id="базовое-использование"><a href="#базовое-использование" class="header-anchor">#</a> Базовое использование</h2><p>Следующий пример использует свойство <code>vars</code> для создания новой переменной <strong>activeNav</strong>, которая становится доступной в жизненном цикле страницы, включая макеты и фрагменты, используемые на странице. Переменная доступна через Twig-переменную <code>{{ activeNav }}</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[activeNav]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">blog</span>&#39;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> activeNav <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The blog is active!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h2 id="внедрение-переменных"><a href="#внедрение-переменных" class="header-anchor">#</a> Внедрение переменных</h2><p>Компонент resources позволяет определять любое количество переменных на странице. Они становятся доступны макету как обычные Twig-переменные.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[activeNav]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">blog</span>&#39;</span>
</code></pre></div><p>Вы также можете использовать параметры из цикла страницы. В следующем примере переменная <code>activeNav</code> будет содержать значение из маршрута страницы <code>:slug</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">mypage/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[activeNav]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">{{ :slug }}</span>&#39;</span>
</code></pre></div><p>Эта концепция также работает для переменных компонентов. Следующий пример ищет автора по <code>:slug</code> из маршрута страницы, а затем назначает <code>author.id</code> переменной страницы <strong>authorIdPage</strong>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/author/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section author</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[authorIdPage]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">Author ID is: {{ author.id }}</span>&#39;</span>
</code></pre></div><h2 id="внедрение-ресурсов"><a href="#внедрение-ресурсов" class="header-anchor">#</a> Внедрение ресурсов</h2><p>Если макет включает стандартные теги <code>{% scripts %}</code> и <code>{% styles %}</code>, можно внедрять ресурсы в эти заполнители. Ресурсы будут объединены и скомбинированы в единую ссылку на скрипт/стиль.</p><p>Ресурсы, загруженные через компонент resources, должны находиться в определённой папке внутри темы, как описано в доступных свойствах. Пример — фрагмент с именем <strong>blocks/carousel.htm</strong></p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">css[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.css</span>&quot;</span>
<span class="token key attr-name">scss[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.scss</span>&quot;</span>
<span class="token key attr-name">less[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.less</span>&quot;</span>
<span class="token key attr-name">js[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.js</span>&quot;</span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Carousel Contents Here --&gt;</span>
</code></pre></div></div><p>Теперь, когда фрагмент загружен на страницу, скрипты и стили будут внедрены в макет. Ресурсы должны располагаться в директориях <strong>assets/js/blocks/carousel.js</strong> и <strong>assets/less/blocks/carousel.less</strong> соответственно.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Assets for the carousel are injected automatically --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blocks/carousel<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>При двойном использовании фрагмента на странице ресурсы будут внедрены только один раз.</p></div><h2 id="использование-пользовательских-заголовков"><a href="#использование-пользовательских-заголовков" class="header-anchor">#</a> Использование пользовательских заголовков</h2><p>В качестве примера определения пользовательских заголовков вы можете отрендерить XML-контент на странице вместо HTML. Это возможно путём внедрения заголовка <code>Content-Type</code> на страницу со значением <strong>text/xml</strong>. Этот заголовок будет отправлен с ответом при загрузке страницы.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/rss</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">headers[Content-Type]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">text/xml</span>&#39;</span>
</code></pre></div><div class="language-xml extra-class"><pre class="language-xml"><code><span class="token prolog">&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot;?&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>rss</span> <span class="token attr-name">version</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>2.0<span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token namespace">xmlns:</span>atom</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>http://www.w3.org/2005/Atom<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- RSS contents here --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>rss</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div>`,24))])}const x=o(u,[["render",i]]);export{q as __pageData,x as default};
